const SURP_IDS = new Set(["V2-179", "V2-172", "V2-173", "V2-184", "V2-185", "V2-190", "V2-191", "V2-194", "V2-195", "V2-199", "V2-203", "V2-204", "V2-208"]);
const RECON_IDS = new Set(["V2-196", "V2-197"]);
// Aplica o "set": ideias de surpresa que não vêm de uma base de surpresa ganham as regras de surpresa segura.
export const flameMoreVariants = (variants) => FLAME_MORE_BASES.map(({ id, from, title, set }) => {
  const origin = variants.find((variant) => variant.id === from);
  const extra = SURP_IDS.has(id) && !origin.surpriseLevel ? SURP : RECON_IDS.has(id) ? RECON : {};
  return { ...origin, id, title, flame: true, ...extra, ...(set ?? {}) };
});

export const FLAME_MORE_T = {
  pt: {
    "V2-170": ["Dia de pijama a dois, sem relógio","Um dia inteiro sem horário deixa o corpo e a conversa soltarem. O carinho aparece sozinho quando ninguém está com pressa.",["Combinem antes: hoje não há tarefa, visita ou tela, e qualquer um pode pedir para mudar o ritmo a qualquer momento.","Fiquem de pijama e deixem a casa na penumbra, com café, chá e algo simples para beliscar.","Alternem blocos: um tempo de conversa, um de música, um de colo, um de silêncio lado a lado.","A cada bloco, cada um pede uma coisa pequena: um cafuné, um abraço, uma história antiga.","À noite, escolham juntos o que querem repetir no próximo domingo."],"Deixem o celular em outro cômodo e peguem só para uma foto, se quiserem guardar o dia.",null,null],
    "V2-171": ["Dia de ateliê a dois: retratos de olhos fechados","Desenhar o outro de olhos fechados vira brincadeira de toque e de riso, e o resultado sempre é engraçado e terno.",["Combinem que ninguém precisa saber desenhar e que tocar só vale no rosto, nas mãos e nos braços, e só se os dois toparem.","Preparem papel grande, lápis e uma música tranquila.","Um fecha os olhos e desenha o rosto do outro seguindo o toque nas mãos e no rosto, devagar.","Troquem, comparem os retratos e deem um título carinhoso a cada um.","Pendurem os desenhos e passem a tarde fazendo outros: de mãos, de pés, de sorrisos."],"Assinem os retratos com a data. Daqui a um ano vão adorar reler.",null,null],
    "V2-172": ["Dia do cardápio secreto","Um dia com três pequenos momentos preparados em segredo mostra cuidado e deixa o outro com curiosidade o dia inteiro.",["Quem prepara combina com o outro só o essencial: que haverá 3 surpresas pequenas e que qualquer uma pode ser trocada por um simples 'agora não'.","Prepare às escondidas 3 momentos: um café da manhã na cama, um lanche com bilhete e um jantar à luz de velas.","Entregue um bilhete em cada momento, com uma dica do que vem a seguir.","Quem recebe só precisa aproveitar e dizer, ao fim de cada momento, o que mais gostou.","À noite, invertam: o outro prepara um bilhete para o próximo domingo."],"Escolham antes uma palavra que significa 'quero uma pausa', sem explicação.",null,"Um prepara o cardápio em segredo; o outro só descobre a cada hora."],
    "V2-173": ["Dia de palco em casa: dança, luz baixa e figurino","Vestir algo de que o outro gosta e dançar sem plateia solta o riso e o brilho nos olhos.",["Combinem antes: cada um escolhe um figurino que se sinta bem usando, e dançar só vale se os dois estiverem confortáveis.","Montem o palco na sala: móveis para o lado, luz baixa e uma lista de músicas.","Cada um faz uma apresentação curta para o outro, de dança, mímica ou dublagem.","Dancem juntos uma música lenta, olho no olho, e uma bem animada.","No fim, entreguem um 'prêmio' simples: um beijo, um aplauso ou um abraço longo."],"Gravem só o áudio da última música e guardem para ouvir daqui a um ano.",null,"Cada um escolhe, em segredo, o figurino e a música do outro."],
    "V2-174": ["Dia de reviver: da primeira mensagem ao primeiro beijo","Refazer a história do casal, do começo até hoje, reacende o desejo de se escolher outra vez.",["Combinem que o dia é de lembranças boas e que qualquer assunto difícil fica para outro dia.","Montem uma linha do tempo no chão com papéis: primeira mensagem, primeiro encontro, primeiro beijo, primeira viagem.","Contem cada momento do ponto de vista de cada um e riam das diferenças.","Releiam as primeiras conversas, ou recriem uma como se fosse hoje.","Ao fim, escrevam o próximo capítulo: três coisas que querem viver juntos este ano."],"Terminem o dia refazendo o primeiro gesto de carinho que trocaram.",null,null],
    "V2-175": ["Dia de cozinha lenta e jantar a dois","Cozinhar sem pressa, com as mãos perto e a conversa solta, é um jeito antigo de se aproximar.",["Combinem o cardápio e a regra: cada um pode pedir para parar ou trocar de tarefa quando quiser.","Escolham uma receita que leve a tarde inteira, com várias etapas.","Dividam as tarefas e troquem a cada etapa: um mexe, o outro prova e opina.","Arrumem a mesa com cuidado, velas e música baixa.","Jantem devagar e, entre uma garfada e outra, digam algo que admiram no outro."],"Anotem a receita no caderno do casal e guardem para repetir.",null,null],
    "V2-176": ["Jogo das verdades, versão romântica","Perguntas boas, respostas sinceras e um beijo de prêmio: o jogo mais simples acende o clima.",["Combinem a regra: qualquer pergunta pode ser trocada por um 'passo', sem explicação.","Cada um escreve 5 perguntas bonitas ou divertidas, como 'o que você mais gosta no meu jeito de te olhar?'.","Misturem os papéis e sorteiem uma pergunta por vez.","Quem responde com sinceridade ganha um beijo ou um carinho à escolha.","Parem quando acabarem as perguntas, ou antes, se algum dos dois preferir."],"Guardem as perguntas mais boas para o próximo jogo.",null,null],
    "V2-177": ["O jogo dos favores: peça, receba e retribua","Pedir carinho com clareza e receber sem pressa é um jeito divertido de se conhecer melhor.",["Combinem que qualquer favor pode ser recusado, sem motivo, e que ninguém fica chateado.","Cada um escreve 6 favores pequenos em papéis, como 'um abraço de 20 segundos' ou 'um cafuné na nuca'.","Em cada rodada, um tira um papel e o outro decide se aceita.","Quem recebe agradece, e quem fez pergunta como foi.","Terminem com o favor mais pedido da noite."],"Guardem o papel favorito para repetir no próximo encontro.",null,null],
    "V2-178": ["Playlist de luz baixa que um prepara para o outro","Escolher músicas para quem a gente ama é uma declaração em forma de som. Ouvir juntos, de olhos fechados, aproxima.",["Combinem a regra: se alguma música incomodar, é só dizer 'pula'.","Cada um monta uma lista de 5 músicas para o outro, sem mostrar, e escreve uma frase sobre cada uma.","Deixem a luz baixa e sentem-se lado a lado ou deitados.","Ouçam as músicas de olhos fechados e, a cada uma, quem fez a lista lê a frase.","Ao fim, cada um diz qual música mais tocou o coração."],"Guardem a lista no celular com o nome do outro.",null,null],
    "V2-179": ["Quiz do que a gente ainda não sabe um do outro","Descobrir o que o outro ainda guarda mostra que o amor também é curiosidade.",["Combinem que qualquer pergunta pode ser trocada por um 'passo'.","Cada um escreve 8 perguntas que nunca fez, de leves a mais íntimas.","Alternem a vez: um pergunta e o outro responde com calma.","A cada resposta, quem perguntou diz o que aprendeu e dá um carinho como agradecimento.","Fechem com a pergunta que mais surpreendeu os dois."],"Anotem as respostas num caderno; vale ouro no futuro.",null,"Cada um prepara em segredo as perguntas, sem mostrar até começar."],
    "V2-180": ["Dez elogios que a gente nunca disse","Elogiar de verdade, com detalhes, vira um presente que dura mais que qualquer objeto.",["Combinem que os elogios são para ouvir, sem responder com 'imagina' ou 'que nada'.","Cada um escreve 10 elogios, de dentro e de fora: o jeito de rir, o cheiro, a forma de cuidar.","Sentem-se de frente, com a luz baixa, e leiam um de cada vez, olhando nos olhos.","Quem ouve só diz 'obrigado' e, se quiser, retribui com um gesto.","No fim, troquem os papéis para guardar."],"Escondam o papel do outro num lugar que ele vai achar em uma semana.",null,null],
    "V2-181": ["Duas músicas, uma dança e um segredo","Dançar devagar abraçados e dividir um segredo bonito faz uma noite curta parecer longa.",["Combinem que o segredo pode ser pequeno e que ninguém precisa contar nada que não queira.","Cada um escolhe uma música que tenha a ver com os dois.","Dancem a primeira, abraçados e sem falar.","Na segunda, cada um sussurra ao ouvido um segredo bom: um desejo, uma lembrança, um medo bobo.","Terminem com um abraço e o silêncio que quiserem."],"Troquem o nome das músicas por um apelido só de vocês.",null,null],
    "V2-182": ["Tarde de filme com regra de carinho a cada cena","Um filme deixa de ser só um filme quando cada cena vira um pretexto para chegar mais perto.",["Combinem a regra: se algum carinho não estiver bom, é só avisar e trocar.","Escolham um filme romântico ou engraçado e façam um ninho de cobertores.","Criem regras divertidas: a cada beijo na tela, um beijo na testa; a cada risada, um cafuné.","No intervalo, preparem algo para comer e voltem sem pressa.","Ao fim, digam qual cena mais lembrou os dois."],"Deixem o filme em segundo plano e conversem se a vontade vier.",null,null],
    "V2-183": ["Banho a dois, sem pressa","Água morna, luz suave e conversa baixa transformam um banho em um tempo só dos dois, sem nada a provar.",["Combinem antes o que é bem-vindo e o que não é, e que qualquer um pode sair quando quiser.","Preparem o banheiro: toalhas macias, luz baixa, música tranquila e algo para beber.","Entrem com calma e deixem a água fazer o trabalho: sem pressa, sem olhar para o relógio.","Alternem: um lava as costas do outro com sabonete comum, em silêncio.","Saiam enrolados em toalhas e terminem com chá e conversa baixa."],"Se não tiverem banheira, façam o mesmo com chuveiro morno e pés de molho.",null,null],
    "V2-184": ["Caça ao tesouro do desejo: pistas pela casa","Seguir pistas escondidas e chegar a um abraço deixa o corpo curioso e o clima leve.",["Um prepara 5 pistas e combina com o outro só a regra: tudo é brincadeira e dá para parar quando quiser.","Esconda pelos cômodos bilhetes com charadas e pequenos elogios.","Quem procura segue as pistas, e em cada uma ganha um carinho ou uma frase de amor.","A última pista leva a algo simples: um abraço longo, uma música e uma sobremesa para dividir.","Depois, invertam: o outro prepara o próximo desafio."],"Guardem os bilhetes numa caixinha.",null,"Um esconde as pistas pela casa; o outro só descobre ao seguir cada uma."],
    "V2-185": ["Sobremesa às cegas e conversa baixa","Sem ver, o paladar e o toque ficam mais atentos, e a conversa vai ficando mais baixa e mais próxima.",["Combinem antes o que é bem-vindo e que qualquer um pode tirar a venda quando quiser.","Um prepara 4 sabores doces simples, como fruta, chocolate, mel e queijo.","O outro senta de olhos vendados e prova um a um, adivinhando.","Entre uma prova e outra, conversem baixinho sobre o sabor e a lembrança que ele traz.","Troquem e terminem com um abraço e um sabor à escolha dos dois."],"Usem colheres pequenas e guardanapo à mão para não perder o clima.",null,"Quem prepara escolhe os sabores sem contar; o outro só prova."],
    "V2-186": ["Tarde de fotos: por que a gente se escolheu","Olhar fotos antigas lembra como começou e reacende o desejo de escolher o outro de novo.",["Combinem que a tarde é de lembranças boas, sem cobranças.","Separem 10 fotos do casal, de épocas diferentes.","Para cada uma, cada um diz o que sentiu naquele dia e o que o atraiu no outro.","Escrevam atrás da foto uma frase carinhosa e a data de hoje.","No fim, escolham a favorita e coloquem num lugar visível."],"Imprimam uma foto nova hoje e escrevam atrás: 'agora'.",null,null],
    "V2-187": ["Tarde do álbum de promessas","Promessas pequenas e possíveis, escritas à mão, valem mais que grandes juras que não se cumprem.",["Combinem que as promessas são livres, curtas e que ninguém é obrigado a prometer o que não quer.","Cada um escreve 5 promessas simples: 'vou te abraçar mais ao chegar em casa', 'vou olhar para você ao conversar'.","Leiam em voz alta, devagar, com a mão do outro na sua.","Colem tudo num álbum ou num caderno, com desenhos e fotos.","Marquem uma data para reler e ver o que cumpriram."],"Façam uma promessa para os dois, escrita juntos.",null,null],
    "V2-188": ["Caminhada com a regra do beijo a cada cem passos","Contar passos de mãos dadas e trocar um beijo a cada marco é um jeito leve de flertar em público.",["Combinem a regra: o beijo só vale se os dois estiverem à vontade, e em público vale só o que cabe em público.","Escolham um caminho tranquilo e saiam de mãos dadas.","A cada cem passos, parem e troquem um beijo, um elogio ou um sorriso.","Revezem quem escolhe a próxima esquina.","No final, sentem num banco e digam qual foi a parada mais bonita."],"Se o caminho estiver cheio, troquem o beijo por um sussurro no ouvido.",null,null],
    "V2-189": ["Passeio de mãos dadas, sussurrando segredos","Andar bem juntinhos e falar baixo ao ouvido faz um passeio comum virar encontro de namorados.",["Combinem que os segredos podem ser leves e que ninguém precisa contar o que não quer.","Escolham um passeio tranquilo e andem de mãos dadas ou de braços dados.","A cada esquina, um sussurra ao ouvido do outro um elogio ou uma lembrança.","Parem uma vez para ver algo bonito e fiquem em silêncio.","No fim, façam um brinde com o que tiverem à mão."],"Escolham uma palavra-código só de vocês para sinalizar 'estou adorando'.",null,null],
    "V2-190": ["Mirante com bilhete no bolso","Um bilhete de amor lido num lugar bonito fica na memória por muito tempo.",["Quem prepara escreve em segredo um bilhete carinhoso e combina com o outro só o horário do passeio.","Leve o outro a um mirante ou lugar bonito, sem dizer o motivo.","Lá, entregue o bilhete e deixe a pessoa ler em silêncio.","Depois, façam um brinde com o que tiverem e olhem a paisagem abraçados.","Escrevam juntos uma frase no verso, para guardar."],"Levem uma manta pequena se o vento estiver frio.",null,"Quem organiza escolhe o lugar e o bilhete; o outro só segue."],
    "V2-191": ["Estrelas e sussurros no escuro","Deitados olhando para cima, o corpo desacelera e o sussurro ganha um poder especial.",["Combinem antes o que é bem-vindo e que em público vale só o que cabe em público.","Escolham um lugar seguro e escuro, com manta e luz fraca de lanterna.","Deitem lado a lado, de mãos dadas, e fiquem 5 minutos em silêncio.","Depois, cada um sussurra um desejo para a noite e uma lembrança bonita.","Terminem com um abraço longo, sem pressa de ir embora."],"Levem algo quente para beber e um casaco extra.",null,"Quem organiza escolhe o lugar e leva a manta; o outro só descobre ao chegar."],
    "V2-192": ["Tarde de passeio com paradas para abraçar","Um passeio com pausas de carinho faz o tempo andar devagar e a conversa ficar mais íntima.",["Combinem que as paradas são livres e que qualquer um pode pedir para seguir.","Escolham um passeio sem pressa, com vários lugares para parar.","A cada parada, deem um abraço de 20 segundos e digam uma coisa de que gostam.","Revezem quem escolhe o próximo ponto.","Terminem com um lanche e uma conversa sobre o que sentiram."],"Levem uma garrafinha de água e algo para dividir.",null,null],
    "V2-193": ["Tarde de cidade: fingir que acabaram de se conhecer","Fingir que se acabaram de conhecer traz de volta o frio na barriga dos primeiros encontros.",["Combinem a brincadeira: hoje vocês são dois desconhecidos que se simpatizaram, e podem sair do personagem quando quiserem.","Cada um chega separado a um lugar combinado, como se fosse o primeiro encontro.","Conversem como quem se conhece agora, com perguntas curiosas e flertes leves.","Passeiem pelo bairro e, no fim, 'se despeçam' com um beijo.","Contem, no caminho de volta, o que sentiram."],"Escolham nomes de brincadeira para a tarde.",null,null],
    "V2-194": ["Piquenique surpresa: um prepara, o outro só segue","Ser cuidado sem precisar decidir nada é um tipo de carinho que o outro raramente recebe.",["Quem prepara combina só o dia, o horário e que haverá uma surpresa boa.","Monte uma cesta simples com manta, algo para comer, algo para beber e um bilhete carinhoso.","Leve o outro a um parque ou a um canto bonito, sem dizer onde.","Ali, sirvam um ao outro, conversem sem pressa e deixem o celular guardado.","No fim, o outro agradece com um gesto que invente na hora."],"Levem um saco para o lixo, para deixar o lugar do jeito que acharam.",null,"Quem prepara escolhe o lugar e o cardápio; o outro só segue."],
    "V2-195": ["Noite ao ar livre com cobertor e lanterna","A noite aberta dá coragem para conversas que de dia ficam guardadas.",["Combinem que em público vale só o que cabe em público e que qualquer um pode pedir para ir embora.","Escolham um lugar seguro, com manta, lanterna e algo quente para beber.","Sentem-se juntos, enrolados na manta, e apaguem a lanterna por alguns minutos.","Contem um desejo e uma lembrança bonita, em voz baixa.","Voltem com calma, de mãos dadas."],"Avisem alguém do lugar para onde vão.",null,"Quem organiza escolhe o lugar e leva a manta; o outro só descobre ao chegar."],
    "V2-196": ["Caminhada para recontar a nossa história","Andar pelos lugares da própria história e contar tudo de novo reacende o carinho e o desejo de continuar.",["Combinem que a caminhada é de lembranças boas e que podem parar quando quiserem.","Escolham um trajeto com 3 ou 4 lugares que importam para os dois.","Em cada lugar, um conta como foi e como se sentiu naquele dia.","Troquem um beijo ou um abraço no lugar mais especial.","No fim, digam um sonho para o próximo ano."],"Tirem uma foto juntos no ponto final.",null,null],
    "V2-197": ["Roteiro dos lugares onde a gente se apaixonou","Voltar aos lugares onde tudo começou é um jeito de dizer 'ainda escolho você'.",["Combinem a regra: se algum lugar trouxer lembranças difíceis, é só pular.","Listem 3 lugares ligados ao começo da história: onde se viram, onde se beijaram, onde se escolheram.","Visitem cada um, com calma, e contem o que lembram.","Em cada parada, façam um gesto de carinho que caiba em público.","Terminem com algo para comer e um brinde ao presente."],"Levem uma foto antiga para comparar com o lugar de hoje.",null,null],
    "V2-198": ["Dia fora, a dois: sem roteiro e com muitos abraços","Um dia sem agenda, longe da rotina, devolve o tempo de olhar e de tocar.",["Combinem que o dia não tem obrigação, e que qualquer um pode pedir uma pausa.","Escolham um lugar ou bairro que gostem e saiam sem horário de voltar.","Parem onde der vontade: um café, um banco, uma praça.","A cada parada, um abraço longo e uma frase boa.","Voltem sem pressa e deixem o dia terminar do jeito que ele quiser."],"Levem uma bolsa pequena com água, lanche e protetor solar, se for preciso.",null,null],
    "V2-199": ["Dia surpresa: um organiza, o outro só segue","Organizar um dia inteiro para o outro mostra atenção, e se deixar levar é um ato de confiança.",["Quem organiza combina só a hora de saída e o que o outro deve levar, e que qualquer parada pode ser trocada.","Prepare 3 paradas simples: uma bonita, uma gostosa e uma só dos dois.","Entregue um bilhete em cada parada, com uma dica da próxima.","Em cada uma, um gesto de carinho que caiba em público.","No fim do dia, o outro diz qual parada foi a melhor."],"Deixem espaço para improvisar, se alguma parada se prolongar.",null,"Quem organiza escolhe tudo; o outro só descobre uma parada de cada vez."],
    "V2-200": ["Dia de reencontro: caminhar, comer e conversar sem pressa","Um dia inteiro de passeio sem tela traz de volta o hábito de se olhar.",["Combinem que hoje o celular fica no bolso e que podem pedir pausa a qualquer hora.","Comecem com uma caminhada tranquila e uma conversa sobre como cada um tem estado.","Parem para comer algo bom e para dizer uma coisa que ficou guardada.","À tarde, façam algo leve juntos: um jardim, uma loja, um banco ao sol.","No fim do dia, digam o que querem repetir."],"Tirem uma foto só para vocês, sem postar.",null,null],
    "V2-201": ["Dia de trem a dois: janela, música e mãos dadas","Viajar lado a lado, olhando a paisagem passar, solta a conversa e aproxima.",["Combinem o destino e a regra: em público vale só o que cabe em público, e podem trocar o plano a qualquer hora.","Peguem um trem para um lugar próximo, sentados lado a lado, com um fone para cada um.","No caminho, dividam uma música e uma lembrança.","Chegando, passeiem sem roteiro e façam uma pausa para comer algo.","Na volta, deixem a cabeça no ombro do outro e deixem a paisagem fazer o resto."],"Confirmem os horários da volta antes de começar o passeio.",null,null],
    "V2-202": ["Petiscos de rua para dividir, um alimenta o outro","Dividir petiscos e dar na boca um do outro faz de um lanche de rua um pequeno ritual a dois.",["Combinem que em público vale só o que cabe em público.","Escolham uma rua ou feira com petiscos variados e deem um orçamento pequeno para os dois.","Cada um escolhe um petisco para o outro, sem mostrar antes.","Dividam em silêncio, dando um bocado na boca do outro e adivinhando o sabor.","Terminem com uma sobremesa para os dois e uma conversa sobre qual foi o favorito."],"Levem guardanapos e água para não estragar o clima.",null,null],
    "V2-203": ["Jantar surpresa com perguntas debaixo do prato","Um jantar com perguntas escondidas faz a mesa virar um lugar de conversa de verdade.",["Quem organiza reserva o lugar e combina só o horário, e que qualquer pergunta pode ser trocada por um 'passo'.","Antes de chegar, escreva 4 perguntas curtas e esconda-as debaixo do prato, do guardanapo e do copo.","Ao longo do jantar, cada um descobre uma pergunta e responde com calma.","Entre as respostas, um brinde e um olhar mais demorado.","Antes da sobremesa, escolham a pergunta que mais gostaram."],"Confirmem a reserva e o cardápio antes de sair.",null,"Quem organiza escolhe o lugar e as perguntas; o outro só descobre ao sentar."],
    "V2-204": ["Cinema com mãos dadas e bilhete secreto","Um bilhete lido no escuro e mãos dadas durante o filme fazem da sessão um pequeno segredo a dois.",["Combinem que em público vale só o que cabe em público.","Quem organiza escolhe o filme e escreve um bilhete curto de amor, sem contar ao outro.","Antes de a sessão começar, entregue o bilhete e deixe o outro ler com a lanterna do celular.","Durante o filme, fiquem de mãos dadas, com a cabeça no ombro.","Na saída, conversem sobre a cena de que mais gostaram."],"Confirmem o horário da sessão antes de sair.",null,"Quem organiza escolhe o filme e o bilhete; o outro só descobre ao chegar."],
    "V2-205": ["Degustação a dois: adivinhe o gosto do outro","Provar coisas boas e adivinhar o que o outro vai gostar mostra o quanto vocês se conhecem.",["Combinem a regra: qualquer sabor pode ser recusado, sem explicação.","Escolham um lugar com degustação, ou montem uma em casa com 4 sabores.","Cada um escolhe um sabor que acha que o outro vai adorar, sem contar.","Provem em silêncio, olhando nos olhos, e comparem as apostas.","Marquem pontos e deem um beijo de prêmio a quem mais acertou."],"Confirmem a disponibilidade e o horário antes de ir.",null,null],
    "V2-206": ["Loja de nicho: um presente-segredo para o outro","Escolher um mimo pequeno com atenção mostra que você presta atenção em quem ama.",["Combinem um valor pequeno e que o presente deve ser simples e de bom gosto.","Entrem juntos na loja e separem-se por 15 minutos para escolher algo.","Reencontrem-se e entreguem os presentes embrulhados em um papel qualquer.","Abram juntos, olhando nos olhos, e digam por que escolheram aquilo.","Terminem com um café e um agradecimento."],"Guardem os presentes como lembrança do dia.",null,null],
    "V2-207": ["Mercado a dois: cozinhar juntos o que escolherem","Escolher ingredientes juntos e cozinhar depois é um jeito sensorial e divertido de se aproximar.",["Combinem que a regra do dia é escolher só o que os dois toparem.","Visitem um mercado ou feira e escolham 4 ingredientes que um conhece e o outro não.","Voltem para casa e cozinhem juntos, sem receita, com música.","Provem um do outro com a colher, e troquem as tarefas a cada etapa.","Jantem à mesa arrumada, com uma vela."],"Anotem o 'prato do dia' e deem um nome a ele.",null,null],
    "V2-208": ["Jantar temático a dois, a rigor","Escolher um tema e se arrumar para ele transforma um jantar comum numa noite que a gente lembra.",["Combinem o tema e que cada um pode pedir para encurtar a noite a qualquer hora.","Escolham um tema simples, como 'Paris dos anos 20' ou 'noite de gala'.","Arrumem-se de acordo e cheguem separados, como num encontro de verdade.","Jantem com calma e conversem em personagem por um tempo.","Terminem com um brinde e voltem juntos, de braços dados."],"Confirmem a reserva e o cardápio antes.",null,"Quem organiza escolhe o tema e o lugar; o outro só descobre ao chegar."],
    "V2-209": ["Jantar lento e longo: o cardápio das perguntas","Um jantar que dura a noite inteira deixa a conversa chegar a lugares que a pressa não alcança.",["Combinem que o jantar é sem celular e que qualquer pergunta pode ser trocada por um 'passo'.","Escolham um lugar tranquilo e peçam algo para dividir.","Em cada prato, uma pergunta: do passado, do presente e do futuro.","Respondam devagar e deixem o outro terminar sem interromper.","Na sobremesa, cada um diz o que levou de mais bonito da conversa."],"Confirmem a reserva antes de sair.",null,null],
    "V2-210": ["Dia de passeio a dois com um cantinho só nosso","Um dia fora e um cantinho que seja só de vocês viram, com o tempo, um símbolo do casal.",["Combinem que o dia é sem obrigação e que qualquer um pode propor uma pausa.","Escolham um passeio com vários lugares e mantenham uma parada livre.","Ao longo do dia, procurem um cantinho que seja só de vocês: um banco, uma sombra, uma vista.","Ali, façam um pequeno ritual: um abraço, uma música ou uma frase.","Deem um nome ao cantinho e voltem outras vezes."],"Tirem uma foto do cantinho para lembrar.",null,null],
    "V2-211": ["Dia para rever a cidade como casal apaixonado","Ver a cidade com olhos de quem acabou de se apaixonar faz o comum parecer novo.",["Combinem que o dia é de olhar, e que podem parar a qualquer hora.","Escolham 3 lugares que viram mil vezes e olhem para eles como turistas.","Em cada um, cada um aponta algo que nunca tinha reparado e que achou bonito.","Façam um gesto de carinho que caiba em público em cada parada.","No fim, escolham o lugar favorito do dia e guardem-no como 'nosso'."],"Levem uma câmera ou o celular só para fotografar detalhes.",null,null],
  },
  es: {
    "V2-170": ["Día de pijama para dos, sin reloj","Un día entero sin horarios deja que el cuerpo y la conversación se suelten. Las caricias llegan solas cuando nadie tiene prisa.",["Acordad antes: hoy no hay tareas, ni visitas, ni pantallas, y cualquiera puede pedir un cambio de ritmo cuando quiera, con un simple 'paso'.","Quedaos en pijama y dejad la casa en penumbra, con café, té y algo sencillo para picar.","Alternad bloques: un rato de charla, otro de música, otro de mimos y otro de silencio, uno al lado del otro.","En cada bloque, cada uno pide algo pequeño: una caricia en el pelo, un abrazo, una historia antigua.","Por la noche, elegid juntos qué queréis repetir el próximo domingo."],"Dejad el móvil en otra habitación y cogedlo solo para una foto, si queréis guardar el día.",null,null],
    "V2-171": ["Día de taller para dos: retratos con los ojos cerrados","Dibujar al otro con los ojos cerrados se vuelve un juego de roces y risas, y el resultado siempre es divertido y tierno.",["Acordad que nadie tiene que saber dibujar y que tocar solo vale en la cara, las manos y los brazos, y solo si los dos queréis. Cualquiera puede decir 'paso'.","Preparad papel grande, lápices y una música tranquila.","Uno cierra los ojos y dibuja la cara del otro siguiendo el roce de las manos en su rostro, despacio.","Cambiad, comparad los retratos y poned a cada uno un título cariñoso.","Colgad los dibujos y pasad la tarde haciendo más: de manos, de pies, de sonrisas."],"Firmad los retratos con la fecha. Dentro de un año os encantará releerlos.",null,null],
    "V2-172": ["Día del menú secreto","Un día con tres pequeños momentos preparados en secreto demuestra cuidado y deja al otro con curiosidad todo el día.",["Quien prepara acuerda con el otro solo lo esencial: que habrá 3 sorpresas pequeñas y que cualquiera puede cambiarse por un simple 'ahora no' o un 'paso'.","Preparad a escondidas 3 momentos: un desayuno en la cama, una merienda con nota y una cena a la luz de las velas.","Entrega una nota en cada momento, con una pista de lo que viene después.","Quien recibe solo tiene que disfrutar y decir, al final de cada momento, lo que más le ha gustado.","Por la noche, cambiad los papeles: el otro prepara una nota para el próximo domingo."],"Elegid antes una palabra que signifique 'quiero una pausa', sin dar explicaciones.",null,"Uno prepara el menú en secreto; el otro lo descubre hora a hora."],
    "V2-173": ["Día de escenario en casa: baile, luz tenue y vestuario","Ponerse algo que le gusta al otro y bailar sin público suelta la risa y hace brillar los ojos.",["Acordad antes: cada uno elige un vestuario con el que se sienta a gusto, y bailar solo vale si los dos estáis cómodos. Cualquiera puede decir 'paso'.","Montad el escenario en el salón: muebles a un lado, luz tenue y una lista de canciones.","Cada uno hace una actuación corta para el otro, de baile, mímica o play-back.","Bailad juntos una canción lenta, mirándoos a los ojos, y otra bien animada.","Al final, entregaos un 'premio' sencillo: un beso, un aplauso o un abrazo largo."],"Grabad solo el audio de la última canción y guardadlo para escucharlo dentro de un año.",null,"Cada uno elige, en secreto, el vestuario y la canción del otro."],
    "V2-174": ["Día para revivir: del primer mensaje al primer beso","Rehacer la historia de la pareja, desde el principio hasta hoy, reaviva las ganas de elegiros otra vez.",["Acordad que el día es de buenos recuerdos y que cualquier tema difícil se queda para otro día. Cualquiera puede decir 'paso'.","Montad una línea del tiempo en el suelo con papeles: primer mensaje, primera cita, primer beso, primer viaje.","Contad cada momento desde el punto de vista de cada uno y reíos de las diferencias.","Releed las primeras conversaciones, o recread una como si fuera hoy.","Al final, escribid el próximo capítulo: tres cosas que queréis vivir juntos este año."],"Terminad el día repitiendo el primer gesto de cariño que os dedicasteis.",null,null],
    "V2-175": ["Día de cocina lenta y cena para dos","Cocinar sin prisa, con las manos cerca y la charla suelta, es una forma antigua de acercarse.",["Acordad el menú y la regla: cualquiera puede pedir parar o cambiar de tarea cuando quiera, con un 'paso'.","Elegid una receta que lleve toda la tarde, con varios pasos.","Repartid las tareas y cambiad en cada paso: uno remueve, el otro prueba y opina.","Preparad la mesa con mimo, con velas y música baja.","Cenad despacio y, entre bocado y bocado, decid algo que admiráis del otro."],"Apuntad la receta en el cuaderno de la pareja y guardadla para repetirla.",null,null],
    "V2-176": ["Juego de verdades, versión romántica","Buenas preguntas, respuestas sinceras y un beso de premio: el juego más sencillo enciende el ambiente.",["Acordad la regla: cualquier pregunta se puede cambiar por un 'paso', sin explicaciones.","Cada uno escribe 5 preguntas bonitas o divertidas, como '¿qué es lo que más te gusta de cómo te miro?'.","Mezclad los papeles y sacad una pregunta cada vez.","Quien responde con sinceridad gana un beso o una caricia a su elección.","Parad cuando se acaben las preguntas, o antes, si alguno de los dos lo prefiere."],"Guardad las mejores preguntas para el próximo juego.",null,null],
    "V2-177": ["El juego de los favores: pide, recibe y devuelve","Pedir cariño con claridad y recibirlo sin prisa es una forma divertida de conoceros mejor.",["Acordad que cualquier favor se puede rechazar, sin motivo, con un 'paso', y que nadie se ofende.","Cada uno escribe 6 favores pequeños en papelitos, como 'un abrazo de 20 segundos' o 'una caricia en la nuca'.","En cada ronda, uno saca un papel y el otro decide si lo acepta.","Quien recibe da las gracias, y quien lo ha hecho pregunta qué tal ha estado.","Terminad con el favor más pedido de la noche."],"Guardad el papelito favorito para repetirlo en la próxima cita.",null,null],
    "V2-178": ["Lista de canciones a media luz que uno prepara para el otro","Elegir canciones para quien amamos es una declaración hecha música. Escucharlas juntos, con los ojos cerrados, acerca.",["Acordad la regla: si alguna canción incomoda, basta con decir 'paso' y se salta.","Cada uno monta una lista de 5 canciones para el otro, sin enseñarla, y escribe una frase sobre cada una.","Dejad la luz tenue y sentaos uno al lado del otro, o tumbaos.","Escuchad las canciones con los ojos cerrados y, en cada una, quien hizo la lista lee su frase.","Al final, cada uno dice qué canción le tocó más el corazón."],"Guardad la lista en el móvil con el nombre del otro.",null,null],
    "V2-179": ["Test de lo que todavía no sabemos el uno del otro","Descubrir lo que el otro aún guarda demuestra que el amor también es curiosidad.",["Acordad que cualquier pregunta se puede cambiar por un 'paso'.","Cada uno escribe 8 preguntas que nunca ha hecho, de las más ligeras a las más íntimas.","Turnaos: uno pregunta y el otro responde con calma.","Con cada respuesta, quien preguntó dice qué ha aprendido y da una caricia como agradecimiento.","Cerrad con la pregunta que más os sorprendió a los dos."],"Apuntad las respuestas en un cuaderno; dentro de un tiempo valdrán oro.",null,"Cada uno prepara las preguntas en secreto, sin enseñarlas hasta empezar."],
    "V2-180": ["Diez piropos que nunca dijimos","Elogiar de verdad, con detalles, es un regalo que dura más que cualquier objeto.",["Acordad que los piropos son para escucharlos, sin responder con un 'qué va' o 'no es para tanto'. Y que cualquiera puede decir 'paso'.","Cada uno escribe 10 piropos, de dentro y de fuera: la forma de reír, el olor, el modo de cuidar.","Sentaos frente a frente, con luz tenue, y leed uno cada vez, mirándoos a los ojos.","Quien escucha solo dice 'gracias' y, si quiere, responde con un gesto.","Al final, intercambiad los papeles para guardarlos."],"Esconded el papel del otro en un sitio donde lo encuentre dentro de una semana.",null,null],
    "V2-181": ["Dos canciones, un baile y un secreto","Bailar despacio, abrazados, y compartir un secreto bonito hace que una noche corta parezca larga.",["Acordad que el secreto puede ser pequeño y que nadie tiene que contar nada que no quiera. Cualquiera puede decir 'paso'.","Cada uno elige una canción que tenga que ver con los dos.","Bailad la primera, abrazados y sin hablar.","En la segunda, cada uno susurra al oído un secreto bonito: un deseo, un recuerdo, un miedo tonto.","Terminad con un abrazo y el silencio que os apetezca."],"Cambiad el nombre de las canciones por un apodo solo vuestro.",null,null],
    "V2-182": ["Tarde de peli con regla de cariño en cada escena","Una película deja de ser solo una película cuando cada escena es una excusa para acercarse más.",["Acordad la regla: si alguna caricia no os gusta, basta con avisar y cambiarla. Cualquiera puede decir 'paso'.","Elegid una película romántica o divertida y haced un nido de mantas.","Inventad reglas divertidas: con cada beso en la pantalla, un beso en la frente; con cada risa, una caricia en el pelo.","En el descanso, preparad algo de picar y volved sin prisa.","Al final, decid qué escena os recordó más a vosotros."],"Dejad la película de fondo y charlad si os apetece.",null,null],
    "V2-183": ["Baño para dos, sin prisa","Agua tibia, luz suave y charla baja convierten un baño en un rato solo vuestro, sin nada que demostrar.",["Acordad antes qué es bienvenido y qué no, y que cualquiera puede salir cuando quiera, con un 'paso'.","Preparad el baño: toallas suaves, luz tenue, música tranquila y algo de beber.","Entrad con calma y dejad que el agua haga su trabajo: sin prisa, sin mirar el reloj.","Turnaos: uno enjabona la espalda del otro con jabón normal, en silencio.","Salid envueltos en toallas y terminad con una infusión y charla bajita."],"Si no tenéis bañera, haced lo mismo con una ducha tibia y los pies en remojo.",null,null],
    "V2-184": ["Búsqueda del tesoro del deseo: pistas por la casa","Seguir pistas escondidas y acabar en un abrazo despierta la curiosidad y deja el ambiente ligero.",["Uno prepara 5 pistas y acuerda con el otro solo la regla: todo es un juego y se puede parar cuando se quiera, con un 'paso'.","Esconde por las habitaciones notas con acertijos y pequeños piropos.","Quien busca sigue las pistas y, en cada una, gana una caricia o una frase de amor.","La última pista lleva a algo sencillo: un abrazo largo, una canción y un postre para compartir.","Después, cambiad: el otro prepara el siguiente reto."],"Guardad las notas en una cajita.",null,"Uno esconde las pistas por la casa; el otro las descubre siguiendo cada una."],
    "V2-185": ["Postre a ciegas y charla baja","Sin ver, el gusto y el tacto se vuelven más atentos, y la conversación se va haciendo más baja y más cercana.",["Acordad antes qué es bienvenido y que cualquiera puede quitarse la venda cuando quiera, con un 'paso'.","Uno prepara 4 sabores dulces sencillos, como fruta, chocolate, miel y queso.","El otro se sienta con los ojos vendados y los prueba uno a uno, adivinando.","Entre cata y cata, hablad bajito del sabor y del recuerdo que trae.","Cambiad y terminad con un abrazo y un sabor a elegir entre los dos."],"Usad cucharillas pequeñas y tened una servilleta a mano para no romper el ambiente.",null,"Quien prepara elige los sabores sin decir nada; el otro solo prueba."],
    "V2-186": ["Tarde de fotos: por qué nos elegimos","Mirar fotos antiguas recuerda cómo empezó todo y reaviva las ganas de elegir al otro de nuevo.",["Acordad que la tarde es de buenos recuerdos, sin reproches. Cualquiera puede decir 'paso'.","Separad 10 fotos de la pareja, de épocas distintas.","Con cada una, cada uno dice qué sintió ese día y qué le atrajo del otro.","Escribid detrás de la foto una frase cariñosa y la fecha de hoy.","Al final, elegid la favorita y ponedla en un lugar visible."],"Imprimid hoy una foto nueva y escribid detrás: 'ahora'.",null,null],
    "V2-187": ["Tarde del álbum de promesas","Las promesas pequeñas y posibles, escritas a mano, valen más que grandes juramentos que no se cumplen.",["Acordad que las promesas son libres, cortas y que nadie está obligado a prometer lo que no quiere. Cualquiera puede decir 'paso'.","Cada uno escribe 5 promesas sencillas: 'te abrazaré más al llegar a casa', 'te miraré a los ojos cuando hablemos'.","Leedlas en voz alta, despacio, con la mano del otro en la vuestra.","Pegadlo todo en un álbum o en un cuaderno, con dibujos y fotos.","Marcad una fecha para releerlas y ver qué habéis cumplido."],"Haced una promesa para los dos, escrita entre ambos.",null,null],
    "V2-188": ["Paseo con la regla del beso cada cien pasos","Contar pasos de la mano y darse un beso en cada marca es una forma ligera de coquetear en público.",["Acordad la regla: el beso solo vale si los dos estáis a gusto, y en público solo vale lo que cabe en público. Cualquiera puede decir 'paso'.","Elegid un camino tranquilo y salid de la mano.","Cada cien pasos, parad e intercambiad un beso, un piropo o una sonrisa.","Turnaos para elegir la próxima esquina.","Al final, sentaos en un banco y decid cuál fue la parada más bonita."],"Si el camino está lleno de gente, cambiad el beso por un susurro al oído.",null,null],
    "V2-189": ["Paseo de la mano, susurrando secretos","Caminar muy juntos y hablarse bajito al oído convierte un paseo cualquiera en una cita de enamorados.",["Acordad que los secretos pueden ser ligeros y que nadie tiene que contar lo que no quiera. Cualquiera puede decir 'paso'.","Elegid un paseo tranquilo y andad de la mano o del brazo.","En cada esquina, uno susurra al oído del otro un piropo o un recuerdo.","Parad una vez a mirar algo bonito y quedaos en silencio.","Al final, brindad con lo que tengáis a mano."],"Elegid una palabra clave solo vuestra para decir 'me está encantando'.",null,null],
    "V2-190": ["Mirador con nota en el bolsillo","Una nota de amor leída en un lugar bonito se queda en la memoria mucho tiempo.",["Quien prepara escribe en secreto una nota cariñosa y acuerda con el otro solo la hora del paseo.","Lleva al otro a un mirador o a un lugar bonito, sin decirle el motivo.","Allí, entrégale la nota y deja que la lea en silencio.","Después, brindad con lo que tengáis y mirad el paisaje abrazados.","Escribid juntos una frase en el reverso, para guardarla."],"Llevad una mantita pequeña por si hace fresco.",null,"Quien organiza elige el lugar y la nota; el otro solo se deja llevar."],
    "V2-191": ["Estrellas y susurros en la oscuridad","Tumbados mirando hacia arriba, el cuerpo se calma y el susurro cobra un poder especial.",["Acordad antes qué es bienvenido y que en público solo vale lo que cabe en público. Cualquiera puede decir 'paso'.","Elegid un lugar seguro y oscuro, con manta y una linterna de luz débil.","Tumbaos uno al lado del otro, de la mano, y quedaos 5 minutos en silencio.","Después, cada uno susurra un deseo para la noche y un recuerdo bonito.","Terminad con un abrazo largo, sin prisa por marcharos."],"Llevad algo caliente para beber y una chaqueta de más.",null,"Quien organiza elige el lugar y lleva la manta; el otro lo descubre al llegar."],
    "V2-192": ["Tarde de paseo con paradas para abrazarse","Un paseo con pausas de cariño hace que el tiempo vaya más despacio y la charla se vuelva más íntima.",["Acordad que las paradas son libres y que cualquiera puede pedir seguir andando, con un 'paso'.","Elegid un paseo sin prisa, con varios sitios donde parar.","En cada parada, dadle un abrazo de 20 segundos y decid algo que os gusta.","Turnaos para elegir el siguiente punto.","Terminad con una merienda y una charla sobre lo que habéis sentido."],"Llevad una botellita de agua y algo para compartir.",null,null],
    "V2-193": ["Tarde por la ciudad: fingir que acabáis de conoceros","Fingir que os acabáis de conocer devuelve las mariposas en el estómago de las primeras citas.",["Acordad el juego: hoy sois dos desconocidos que se han caído bien, y podéis salir del personaje cuando queráis, con un 'paso'.","Cada uno llega por separado a un sitio acordado, como si fuera la primera cita.","Hablad como quien se conoce ahora, con preguntas curiosas y flirteos ligeros.","Pasead por el barrio y, al final, 'despedíos' con un beso.","Contaos, de vuelta a casa, lo que habéis sentido."],"Elegid nombres de broma para la tarde.",null,null],
    "V2-194": ["Pícnic sorpresa: uno prepara, el otro se deja llevar","Que te cuiden sin tener que decidir nada es un tipo de cariño que rara vez se recibe.",["Quien prepara acuerda solo el día, la hora y que habrá una buena sorpresa. Cualquiera puede decir 'paso'.","Monta una cesta sencilla con manta, algo de comer, algo de beber y una nota cariñosa.","Lleva al otro a un parque o a un rincón bonito, sin decirle dónde.","Allí, serviros el uno al otro, charlad sin prisa y dejad el móvil guardado.","Al final, el otro da las gracias con un gesto que se invente en el momento."],"Llevad una bolsa para la basura y dejad el lugar tal como lo encontrasteis.",null,"Quien prepara elige el lugar y el menú; el otro solo se deja llevar."],
    "V2-195": ["Noche al aire libre con manta y linterna","La noche abierta da valor para las conversaciones que de día se quedan guardadas.",["Acordad que en público solo vale lo que cabe en público y que cualquiera puede pedir irse, con un 'paso'.","Elegid un lugar seguro, con manta, linterna y algo caliente para beber.","Sentaos juntos, envueltos en la manta, y apagad la linterna unos minutos.","Contaos un deseo y un recuerdo bonito, en voz baja.","Volved con calma, de la mano."],"Avisad a alguien de adónde vais.",null,"Quien organiza elige el lugar y lleva la manta; el otro lo descubre al llegar."],
    "V2-196": ["Caminata para recontar nuestra historia","Pasear por los lugares de vuestra propia historia y contarlo todo otra vez reaviva el cariño y las ganas de seguir.",["Acordad que la caminata es de buenos recuerdos y que podéis parar cuando queráis, con un 'paso'.","Elegid un recorrido con 3 o 4 sitios que importen a los dos.","En cada lugar, uno cuenta cómo fue y cómo se sintió ese día.","Intercambiad un beso o un abrazo en el sitio más especial.","Al final, decid un sueño para el próximo año."],"Haceos una foto juntos en el punto final.",null,null],
    "V2-197": ["Ruta de los lugares donde nos enamoramos","Volver a los sitios donde empezó todo es una forma de decir 'te sigo eligiendo'.",["Acordad la regla: si algún lugar trae recuerdos difíciles, basta con decir 'paso' y saltárselo.","Haced una lista de 3 lugares ligados al comienzo de la historia: donde os visteis, donde os besasteis, donde os elegisteis.","Visitad cada uno con calma y contad lo que recordáis.","En cada parada, tened un gesto de cariño que quepa en público.","Terminad con algo de comer y un brindis por el presente."],"Llevad una foto antigua para compararla con el lugar de hoy.",null,null],
    "V2-198": ["Día fuera, los dos: sin plan y con muchos abrazos","Un día sin agenda, lejos de la rutina, devuelve el tiempo de mirarse y tocarse.",["Acordad que el día no tiene obligaciones y que cualquiera puede pedir una pausa, con un 'paso'.","Elegid un lugar o un barrio que os guste y salid sin hora de vuelta.","Parad donde os apetezca: un café, un banco, una plaza.","En cada parada, un abrazo largo y una frase bonita.","Volved sin prisa y dejad que el día termine como quiera."],"Llevad un bolso pequeño con agua, algo de picar y protector solar, si hace falta.",null,null],
    "V2-199": ["Día sorpresa: uno organiza, el otro se deja llevar","Organizar un día entero para el otro demuestra atención, y dejarse llevar es un acto de confianza.",["Quien organiza acuerda solo la hora de salida y lo que el otro debe llevar, y que cualquier parada se puede cambiar con un 'paso'.","Prepara 3 paradas sencillas: una bonita, una rica y una solo de los dos.","Entrega una nota en cada parada, con una pista de la siguiente.","En cada una, un gesto de cariño que quepa en público.","Al final del día, el otro dice cuál fue la mejor parada."],"Dejad espacio para improvisar, si alguna parada se alarga.",null,"Quien organiza lo elige todo; el otro descubre una parada cada vez."],
    "V2-200": ["Día de reencuentro: caminar, comer y charlar sin prisa","Un día entero de paseo sin pantallas devuelve el hábito de mirarse.",["Acordad que hoy el móvil se queda en el bolsillo y que cualquiera puede pedir una pausa a cualquier hora, con un 'paso'.","Empezad con un paseo tranquilo y una charla sobre cómo ha estado cada uno.","Parad a comer algo rico y a decir algo que se había quedado guardado.","Por la tarde, haced algo ligero juntos: un jardín, una tienda, un banco al sol.","Al final del día, decid qué queréis repetir."],"Haceos una foto solo para vosotros, sin publicarla.",null,null],
    "V2-201": ["Día de tren para dos: ventanilla, música y mano con mano","Viajar uno al lado del otro, viendo pasar el paisaje, suelta la conversación y acerca.",["Acordad el destino y la regla: en público solo vale lo que cabe en público, y podéis cambiar el plan en cualquier momento, con un 'paso'.","Coged un tren a un lugar cercano, sentados uno junto al otro, con un auricular para cada uno.","Por el camino, compartid una canción y un recuerdo.","Al llegar, pasead sin plan y haced una pausa para comer algo.","A la vuelta, apoyad la cabeza en el hombro del otro y dejad que el paisaje haga el resto."],"Comprobad los horarios de vuelta antes de empezar el paseo.",null,null],
    "V2-202": ["Tapas callejeras para compartir, uno da de comer al otro","Compartir tapas y dárselas en la boca el uno al otro convierte un tentempié callejero en un pequeño ritual para dos.",["Acordad que en público solo vale lo que cabe en público, y que cualquiera puede decir 'paso'.","Elegid una calle o un mercadillo con tapas variadas y fijad un presupuesto pequeño para los dos.","Cada uno elige una tapa para el otro, sin enseñarla antes.","Compartidlas en silencio, dándoos un bocado en la boca y adivinando el sabor.","Terminad con un postre para los dos y una charla sobre cuál fue la favorita."],"Llevad servilletas y agua para no estropear el ambiente.",null,null],
    "V2-203": ["Cena sorpresa con preguntas bajo el plato","Una cena con preguntas escondidas convierte la mesa en un lugar de conversación de verdad.",["Quien organiza reserva el sitio y acuerda solo la hora, y que cualquier pregunta se puede cambiar por un 'paso'.","Antes de llegar, escribe 4 preguntas cortas y escóndelas bajo el plato, la servilleta y el vaso.","A lo largo de la cena, cada uno descubre una pregunta y responde con calma.","Entre respuesta y respuesta, un brindis y una mirada más larga.","Antes del postre, elegid la pregunta que más os ha gustado."],"Confirmad la reserva y el menú antes de salir.",null,"Quien organiza elige el lugar y las preguntas; el otro lo descubre al sentarse."],
    "V2-204": ["Cine de la mano y nota secreta","Una nota leída en la oscuridad y las manos unidas durante la película convierten la sesión en un pequeño secreto para dos.",["Acordad que en público solo vale lo que cabe en público, y que cualquiera puede decir 'paso'.","Quien organiza elige la película y escribe una nota corta de amor, sin decírselo al otro.","Antes de que empiece la sesión, entrega la nota y deja que el otro la lea con la linterna del móvil.","Durante la película, id de la mano, con la cabeza en el hombro.","A la salida, charlad sobre la escena que más os gustó."],"Comprobad el horario de la sesión antes de salir.",null,"Quien organiza elige la película y la nota; el otro lo descubre al llegar."],
    "V2-205": ["Cata para dos: adivina el gusto del otro","Probar cosas ricas y adivinar lo que le gustará al otro demuestra cuánto os conocéis.",["Acordad la regla: cualquier sabor se puede rechazar, con un 'paso', sin explicaciones.","Elegid un sitio con catas, o montad una en casa con 4 sabores.","Cada uno elige un sabor que cree que le encantará al otro, sin decirlo.","Probad en silencio, mirándoos a los ojos, y comparad las apuestas.","Apuntad los puntos y dad un beso de premio a quien más haya acertado."],"Confirmad la disponibilidad y el horario antes de ir.",null,null],
    "V2-206": ["Tienda con encanto: un regalo secreto para el otro","Elegir un detalle pequeño con atención demuestra que te fijas en quien amas.",["Acordad un importe pequeño y que el regalo sea sencillo y con buen gusto. Cualquiera puede decir 'paso'.","Entrad juntos en la tienda y separaos 15 minutos para elegir algo.","Reuníos de nuevo y entregaos los regalos envueltos en cualquier papel.","Abridlos juntos, mirándoos a los ojos, y decid por qué habéis elegido eso.","Terminad con un café y un agradecimiento."],"Guardad los regalos como recuerdo del día.",null,null],
    "V2-207": ["Mercado para dos: cocinar juntos lo que elijáis","Elegir ingredientes juntos y cocinar después es una forma sensorial y divertida de acercarse.",["Acordad que la regla del día es elegir solo lo que a los dos os apetezca, y que cualquiera puede decir 'paso'.","Visitad un mercado y elegid 4 ingredientes que uno conozca y el otro no.","Volved a casa y cocinad juntos, sin receta, con música.","Probad del cacillo el uno del otro y cambiad de tarea en cada paso.","Cenad en la mesa preparada, con una vela."],"Apuntad el 'plato del día' y ponedle un nombre.",null,null],
    "V2-208": ["Cena temática para dos, de gala","Elegir un tema y arreglarse para él convierte una cena normal en una noche para recordar.",["Acordad el tema y que cualquiera puede pedir acortar la noche a cualquier hora, con un 'paso'.","Elegid un tema sencillo, como 'París de los años 20' o 'noche de gala'.","Arreglaos en consecuencia y llegad por separado, como en una cita de verdad.","Cenad con calma y charlad un rato metidos en el personaje.","Terminad con un brindis y volved juntos, del brazo."],"Confirmad la reserva y el menú antes.",null,"Quien organiza elige el tema y el lugar; el otro lo descubre al llegar."],
    "V2-209": ["Cena lenta y larga: el menú de las preguntas","Una cena que dura toda la noche deja que la conversación llegue adonde la prisa no alcanza.",["Acordad que la cena es sin móvil y que cualquier pregunta se puede cambiar por un 'paso'.","Elegid un sitio tranquilo y pedid algo para compartir.","En cada plato, una pregunta: del pasado, del presente y del futuro.","Responded despacio y dejad que el otro termine sin interrumpir.","En el postre, cada uno dice lo más bonito que se lleva de la conversación."],"Confirmad la reserva antes de salir.",null,null],
    "V2-210": ["Día de paseo para dos con un rinconcito solo nuestro","Un día fuera y un rincón solo vuestro acaban siendo, con el tiempo, un símbolo de la pareja.",["Acordad que el día es sin obligaciones y que cualquiera puede proponer una pausa, con un 'paso'.","Elegid un paseo con varios sitios y dejad una parada libre.","A lo largo del día, buscad un rincón que sea solo vuestro: un banco, una sombra, una vista.","Allí, haced un pequeño ritual: un abrazo, una canción o una frase.","Poned nombre al rincón y volved otras veces."],"Haced una foto del rincón para recordarlo.",null,null],
    "V2-211": ["Día para ver la ciudad como enamorados","Ver la ciudad con ojos de recién enamorados hace que lo cotidiano parezca nuevo.",["Acordad que el día es para mirar, y que podéis parar a cualquier hora, con un 'paso'.","Elegid 3 sitios que habéis visto mil veces y miradlos como turistas.","En cada uno, cada uno señala algo en lo que nunca se había fijado y que le parece bonito.","Tened un gesto de cariño que quepa en público en cada parada.","Al final, elegid el lugar favorito del día y guardadlo como 'nuestro'."],"Llevad una cámara o el móvil solo para fotografiar detalles.",null,null],
  },
  en: {
    "V2-170": ["A pyjama day for two, no clock","A whole day without a timetable lets the body and the conversation loosen up. Affection turns up on its own when nobody is in a hurry.",["Agree beforehand: today there are no chores, visitors or screens, and anyone can ask to change the pace at any moment.","Stay in your pyjamas, keep the house softly lit, and have coffee, tea and a little something to nibble.","Take turns in blocks: a stretch of talking, one of music, one of cuddling, one of quiet side by side.","In each block, each of you asks for one small thing: a head scratch, a hug, an old story.","In the evening, choose together what you'd like to repeat next Sunday."],"Leave the phones in another room and pick one up only for a photo, if you'd like to keep the day.",null,null],
    "V2-171": ["A studio day for two: portraits with eyes closed","Drawing each other with your eyes closed becomes a game of touch and laughter, and the result is always funny and tender.",["Agree that nobody needs to know how to draw, that touch is only for the face, hands and arms, and only if you both are happy with it. Anyone can say 'pass'.","Get big sheets of paper, pencils and some calm music.","One closes their eyes and draws the other's face, following the touch of their hands and face, slowly.","Swap, compare the portraits and give each one an affectionate title.","Pin up the drawings and spend the afternoon making more: hands, feet, smiles."],"Sign the portraits with the date. In a year's time you'll love reading them again.",null,null],
    "V2-172": ["The secret menu day","A day with three little moments prepared in secret shows care and keeps the other curious from morning till night.",["Whoever is planning tells the other only the essentials: there will be 3 small surprises, and any of them can be swapped for a simple 'not now'.","Quietly prepare 3 moments: breakfast in bed, a snack with a note, and a candlelit dinner.","Hand over a note at each moment, with a hint of what comes next.","The one receiving just enjoys it and says, at the end of each moment, what they liked most.","In the evening, swap: the other writes a note for next Sunday."],"Choose a word beforehand that means 'I'd like a pause', no explanation needed.",null,"One prepares the menu in secret; the other only finds out as each hour comes."],
    "V2-173": ["A home stage day: dancing, low light and costumes","Wearing something the other likes and dancing with no audience brings out laughter and a sparkle in the eyes.",["Agree beforehand: each picks an outfit they feel good in, and dancing only counts if you're both comfortable. Anyone can say 'pass'.","Set up the stage in the living room: furniture to the side, low light and a playlist.","Each performs a short number for the other: dance, mime or lip-sync.","Dance one slow song together, eye to eye, and one lively one.","At the end, hand out a simple 'prize': a kiss, a round of applause or a long hug."],"Record only the audio of the last song and keep it to listen to in a year.",null,"Each secretly picks the other's outfit and song."],
    "V2-174": ["A day to relive it all: from the first message to the first kiss","Retelling your story as a couple, from the start to today, rekindles the wish to choose each other again.",["Agree that the day is for happy memories, and any difficult subject can wait for another day. Anyone can say 'pass'.","Lay out a timeline on the floor with sheets of paper: first message, first date, first kiss, first trip.","Tell each moment from each of your points of view and laugh at the differences.","Reread your first conversations, or recreate one as if it were happening today.","To finish, write the next chapter: three things you'd like to live together this year."],"End the day by repeating the first gesture of affection you ever shared.",null,null],
    "V2-175": ["A slow cooking day and dinner for two","Cooking without hurry, with hands close and conversation flowing, is an age-old way of drawing nearer.",["Agree on the menu and one rule: either of you can ask to stop or swap jobs whenever you like.","Pick a recipe that takes the whole afternoon, with several stages.","Share the tasks and swap at every stage: one stirs, the other tastes and gives an opinion.","Lay the table with care, candles and soft music.","Dine slowly and, between mouthfuls, say something you admire in the other."],"Write the recipe in your couple's notebook and keep it to repeat.",null,null],
    "V2-176": ["The truth game, romantic edition","Good questions, honest answers and a kiss as a prize: the simplest game lights up the mood.",["Agree the rule: any question can be swapped for a 'pass', no explanation needed.","Each writes 5 lovely or playful questions, like 'what do you love most about the way I look at you?'.","Mix up the slips and draw one question at a time.","Whoever answers honestly earns a kiss or a caress of their choice.","Stop when the questions run out, or sooner if either of you would prefer."],"Keep the best questions for the next game.",null,null],
    "V2-177": ["The favours game: ask, receive and give back","Asking for affection clearly and receiving it slowly is a playful way of getting to know each other better.",["Agree that any favour can be turned down, for no reason, and nobody minds. Anyone can say 'pass'.","Each writes 6 small favours on slips, like 'a 20-second hug' or 'a head scratch at the nape'.","Each round, one draws a slip and the other decides whether to accept.","The receiver says thank you, and the giver asks how it felt.","Finish with the favour that was asked for most that evening."],"Keep your favourite slip to repeat on your next date.",null,null],
    "V2-178": ["A low-light playlist each makes for the other","Choosing songs for someone you love is a declaration in sound. Listening together with your eyes closed brings you closer.",["Agree the rule: if a song doesn't feel right, just say 'skip'.","Each puts together a list of 5 songs for the other, without showing it, and writes one sentence about each.","Keep the light low and sit side by side or lie down.","Listen to the songs with your eyes closed and, at each one, the maker of the list reads their sentence.","At the end, each says which song touched their heart most."],"Save the list on your phone under the other's name.",null,null],
    "V2-179": ["A quiz on what we don't yet know about each other","Discovering what the other still keeps to themselves shows that love is also curiosity.",["Agree that any question can be swapped for a 'pass'.","Each writes 8 questions you've never asked, from light to more intimate.","Take turns: one asks and the other answers calmly.","After each answer, the asker says what they learned and gives a little caress as thanks.","Close with the question that surprised you both most."],"Jot the answers in a notebook; it will be priceless later on.",null,"Each prepares the questions in secret, without showing them until you begin."],
    "V2-180": ["Ten compliments we never said","Giving a real compliment, with detail, is a gift that lasts longer than any object.",["Agree that compliments are for listening to, with no 'oh, stop it' or 'it was nothing' in reply. Anyone can say 'pass' on a compliment they'd rather not hear aloud.","Each writes 10 compliments, inside and out: the way you laugh, your scent, the way you care.","Sit facing each other, with low light, and read one at a time, looking into each other's eyes.","The listener only says 'thank you' and, if they like, returns it with a gesture.","At the end, swap the papers to keep."],"Hide the other's paper somewhere they'll find it in a week.",null,null],
    "V2-181": ["Two songs, one dance and a secret","Dancing slowly in an embrace and sharing a lovely secret makes a short evening feel long.",["Agree that the secret can be small and nobody has to tell anything they don't want to. Anyone can say 'pass'.","Each picks a song that means something to the two of you.","Dance the first one in an embrace, without speaking.","In the second, each whispers a good secret into the other's ear: a wish, a memory, a silly fear.","Finish with a hug and as much silence as you like."],"Rename the songs with a nickname that's just yours.",null,null],
    "V2-182": ["A film afternoon with a caress rule for every scene","A film stops being just a film when every scene becomes a reason to move closer.",["Agree the rule: if any caress doesn't feel right, just say so and swap it. Anyone can say 'pass'.","Choose a romantic or funny film and build a nest of blankets.","Make up playful rules: for every kiss on screen, a kiss on the forehead; for every laugh, a head scratch.","At the interval, get something to eat and come back without hurry.","At the end, say which scene reminded you most of the two of you."],"Let the film play in the background and talk if you feel like it.",null,null],
    "V2-183": ["A bath for two, no hurry","Warm water, soft light and low conversation turn a bath into time just for the two of you, with nothing to prove.",["Agree beforehand what is welcome and what is not, and that either of you can step out whenever you like.","Set up the bathroom: soft towels, low light, calm music and something to drink.","Step in slowly and let the water do the work: no rush, no eye on the clock.","Take turns: one washes the other's back with ordinary soap, in silence.","Step out wrapped in towels and finish with tea and quiet conversation."],"If you don't have a bath, do the same with a warm shower and a foot soak.",null,null],
    "V2-184": ["Desire treasure hunt: clues around the house","Following hidden clues and ending in a hug leaves the body curious and the mood light.",["One prepares 5 clues and tells the other only the rule: it's all play, and you can stop whenever you like. Anyone can say 'pass'.","Hide notes with riddles and little compliments in different rooms.","The seeker follows the clues and, at each one, earns a caress or a line of love.","The last clue leads to something simple: a long hug, a song and a dessert to share.","Afterwards, swap: the other prepares the next challenge."],"Keep the notes in a little box.",null,"One hides the clues around the house; the other only finds out by following each one."],
    "V2-185": ["Blindfolded dessert and low conversation","Without sight, taste and touch grow more attentive, and the conversation gets softer and closer.",["Agree beforehand what is welcome and that either of you can take the blindfold off whenever you like. Anyone can say 'pass'.","One prepares 4 simple sweet tastes, like fruit, chocolate, honey and cheese.","The other sits blindfolded and tries them one by one, guessing.","Between tastes, talk softly about the flavour and the memory it brings.","Swap, and finish with a hug and a taste you both choose."],"Use small spoons and keep a napkin handy so the mood isn't lost.",null,"The one preparing chooses the tastes without telling; the other only tastes."],
    "V2-186": ["A photo afternoon: why we chose each other","Looking at old photos reminds you how it began and rekindles the wish to choose each other again.",["Agree that the afternoon is for happy memories, with no score-settling. Anyone can say 'pass'.","Pick out 10 photos of you as a couple, from different times.","For each one, say what you felt that day and what drew you to the other.","Write a loving sentence and today's date on the back of each photo.","At the end, choose a favourite and put it somewhere you can see it."],"Print a new photo today and write 'now' on the back.",null,null],
    "V2-187": ["The afternoon of the promise album","Small, possible promises written by hand are worth more than grand vows that never come true.",["Agree that promises are free and short, and nobody has to promise what they don't want to. Anyone can say 'pass'.","Each writes 5 simple promises: 'I'll hug you more when I get home', 'I'll look at you when we talk'.","Read them aloud, slowly, with the other's hand in yours.","Stick everything into an album or notebook, with drawings and photos.","Set a date to read them again and see what you've kept."],"Make one promise for the two of you, written together.",null,null],
    "V2-188": ["A walk with a kiss every hundred steps","Counting steps hand in hand and trading a kiss at every milestone is a light way of flirting in public.",["Agree the rule: a kiss only counts if you're both comfortable, and in public, only what is fine in public. Anyone can say 'pass'.","Pick a quiet route and set off hand in hand.","Every hundred steps, stop and trade a kiss, a compliment or a smile.","Take turns choosing the next corner.","At the end, sit on a bench and say which stop was the loveliest."],"If the route is busy, swap the kiss for a whisper in the ear.",null,null],
    "V2-189": ["A stroll hand in hand, whispering secrets","Walking close and speaking softly into an ear turns an ordinary stroll into a date for sweethearts.",["Agree that the secrets can be light and nobody has to share what they'd rather not. Anyone can say 'pass'. In public, only what is fine in public.","Choose a quiet walk and go hand in hand or arm in arm.","At every corner, one whispers a compliment or a memory in the other's ear.","Stop once to look at something beautiful and stay quiet together.","At the end, make a toast with whatever you have at hand."],"Pick a code word that's just yours to signal 'I'm loving this'.",null,null],
    "V2-190": ["A viewpoint with a note in the pocket","A love note read in a beautiful place stays in the memory for a long time.",["Whoever is planning secretly writes a tender note and tells the other only the time of the outing. Anyone can say 'pass' to any part of the plan.","Take the other to a viewpoint or a lovely spot, without saying why.","There, hand over the note and let them read it in silence.","Then make a toast with whatever you have and look at the view in each other's arms. In public, only what is fine in public.","Write a line together on the back, to keep."],"Bring a small blanket if the wind is cold.",null,"The organiser chooses the place and the note; the other just follows."],
    "V2-191": ["Stars and whispers in the dark","Lying down and looking up, the body slows and a whisper gains a special power.",["Agree beforehand what is welcome, that anyone can stop or say 'pass', and that in public, only what is fine in public.","Choose a safe, dark place, with a blanket and a dim torch.","Lie side by side, holding hands, and stay quiet for 5 minutes.","Then each whispers a wish for the night and a lovely memory.","Finish with a long hug, in no hurry to leave."],"Bring something warm to drink and an extra coat.",null,"The organiser chooses the place and brings the blanket; the other only finds out on arrival."],
    "V2-192": ["An afternoon stroll with stops for hugs","A walk with pauses for affection slows time down and makes the conversation more intimate.",["Agree that the stops are free and anyone can ask to keep going. Anyone can say 'pass'. In public, only what is fine in public.","Choose an unhurried walk with plenty of places to pause.","At each stop, share a 20-second hug and say one thing you like.","Take turns choosing the next spot.","Finish with a snack and a chat about how it felt."],"Bring a small bottle of water and something to share.",null,null],
    "V2-193": ["A city afternoon: pretending we've just met","Pretending you've only just met brings back the butterflies of the first dates.",["Agree on the game: today you're two strangers who have taken a liking to each other, and either of you can step out of character whenever you like. Anyone can say 'pass'.","Each arrives separately at an agreed place, as if for a first date.","Talk like people getting to know each other, with curious questions and light flirting.","Stroll around the neighbourhood and, at the end, 'say goodbye' with a kiss. In public, only what is fine in public.","On the way back, tell each other what you felt."],"Choose playful names for the afternoon.",null,null],
    "V2-194": ["Surprise picnic: one prepares, the other just follows","Being looked after without having to decide anything is a kind of care the other rarely gets.",["Whoever is preparing tells the other only the day, the time and that there will be a lovely surprise. Anyone can say 'pass' to any part of it.","Pack a simple basket with a blanket, something to eat, something to drink and a tender note.","Take the other to a park or a pretty corner, without saying where.","There, serve each other, talk without hurry and keep the phones tucked away. In public, only what is fine in public.","At the end, the other says thank you with a gesture they make up on the spot."],"Bring a bag for rubbish, to leave the place as you found it.",null,"The one preparing chooses the place and the menu; the other just follows."],
    "V2-195": ["An outdoor evening with a blanket and a torch","An open night gives courage for conversations that stay tucked away by day.",["Agree that in public, only what is fine in public, and that anyone can stop or ask to head home, or say 'pass'.","Choose a safe spot, with a blanket, a torch and something warm to drink.","Sit close, wrapped in the blanket, and switch the torch off for a few minutes.","Share a wish and a lovely memory, in low voices.","Head back calmly, hand in hand."],"Tell someone where you are going.",null,"The organiser chooses the place and brings the blanket; the other only finds out on arrival."],
    "V2-196": ["A walk to retell our story","Walking through the places of your own story and telling it all again rekindles affection and the wish to carry on.",["Agree that the walk is for happy memories and you can stop whenever you like. Anyone can say 'pass'.","Pick a route with 3 or 4 places that matter to you both.","At each place, one tells how it was and how they felt that day.","Share a kiss or a hug at the most special spot. In public, only what is fine in public.","At the end, each shares a dream for next year."],"Take a photo together at the final stop.",null,null],
    "V2-197": ["A trail of the places where we fell in love","Going back to the places where it all began is a way of saying 'I'd still choose you'.",["Agree the rule: if any place brings back hard memories, just skip it. Anyone can say 'pass'.","List 3 places linked to the start of your story: where you met, where you kissed, where you chose each other.","Visit each one, unhurried, and share what you remember.","At each stop, make a gesture of affection that is fine in public.","Finish with something to eat and a toast to the present."],"Bring an old photo to compare with the place today.",null,null],
    "V2-198": ["A day out for two: no plan and lots of hugs","A day with no agenda, away from routine, gives back the time to look at each other and to touch.",["Agree that the day has no obligations and either of you can ask for a pause. Anyone can say 'pass'.","Choose a place or neighbourhood you both like and head out with no time to be back.","Stop wherever you feel like it: a café, a bench, a square.","At each stop, a long hug and a lovely sentence. In public, only what is fine in public.","Head home unhurried and let the day end the way it wants to."],"Pack a small bag with water, a snack and sun cream, if needed.",null,null],
    "V2-199": ["Surprise day: one plans, the other just follows","Planning a whole day for the other shows attention, and letting yourself be led is an act of trust.",["Whoever is planning tells the other only the departure time and what to bring, and that any stop can be swapped. Anyone can say 'pass'.","Prepare 3 simple stops: a pretty one, a tasty one and one just for the two of you.","Hand over a note at each stop, with a hint of the next.","At each one, share a gesture of affection that is fine in public.","At the end of the day, the other says which stop was the best."],"Leave room to improvise if a stop runs long.",null,"The organiser chooses everything; the other finds out one stop at a time."],
    "V2-200": ["A day to reconnect: walk, eat and talk without hurry","A whole day out without screens brings back the habit of looking at each other.",["Agree that today the phones stay in your pockets and either of you can ask for a pause at any time. Anyone can say 'pass'.","Start with a gentle walk and a chat about how each of you has been.","Stop for something good to eat and to say one thing you've been keeping inside.","In the afternoon, do something light together: a garden, a shop, a bench in the sun.","At the end of the day, say what you'd like to repeat."],"Take one photo just for the two of you, and don't post it.",null,null],
    "V2-201": ["A train day for two: window, music and hand in hand","Travelling side by side, watching the scenery go by, loosens the conversation and brings you closer.",["Agree the destination and the rule: in public, only what is fine in public, and you can change the plan at any time. Anyone can say 'pass'.","Catch a train to somewhere nearby, sitting side by side, one earphone each.","On the way, share a song and a memory.","Once there, wander with no plan and pause to eat something.","On the way back, rest your head on the other's shoulder and let the scenery do the rest."],"Check the return times before you set off.",null,null],
    "V2-202": ["Street snacks to share, feeding each other","Sharing snacks and feeding each other turns a street lunch into a little ritual for two.",["Agree that in public, only what is fine in public. Anyone can stop or say 'pass'.","Pick a street or market with a variety of snacks and set a small budget for the two of you.","Each chooses a snack for the other, without showing it first.","Share quietly, offering each other a bite and guessing the flavour.","Finish with a dessert for two and a chat about which was your favourite."],"Bring napkins and water so nothing spoils the mood.",null,null],
    "V2-203": ["Surprise dinner with questions under the plate","A dinner with hidden questions turns the table into a place for real conversation.",["Whoever is planning books the place and tells the other only the time, and that any question can be swapped for a 'pass'.","Before arriving, write 4 short questions and hide them under the plate, the napkin and the glass.","Through the dinner, each finds a question and answers it calmly.","Between answers, a toast and a longer look. In public, only what is fine in public.","Before dessert, choose the question you liked best."],"Confirm the booking and the menu before you leave.",null,"The organiser chooses the place and the questions; the other only finds out when sitting down."],
    "V2-204": ["Cinema with held hands and a secret note","A note read in the dark and hands held through the film turn the screening into a little secret for two.",["Agree that in public, only what is fine in public. Anyone can say 'pass'.","Whoever is planning picks the film and writes a short love note, without telling the other.","Before the film starts, hand over the note and let the other read it by the light of their phone.","During the film, hold hands, with a head on a shoulder.","On the way out, talk about the scene you liked most."],"Confirm the screening time before you leave.",null,"The organiser chooses the film and the note; the other only finds out on arrival."],
    "V2-205": ["A tasting for two: guess what the other will like","Trying lovely things and guessing what the other will enjoy shows how well you know each other.",["Agree the rule: any taste can be declined, no explanation needed. Anyone can say 'pass'.","Choose a place with a tasting, or set one up at home with 4 flavours.","Each picks a flavour they think the other will adore, without saying.","Taste in silence, looking into each other's eyes, and compare your guesses.","Keep score and give a prize kiss to whoever guessed best."],"Confirm availability and the time before you go.",null,null],
    "V2-206": ["A little shop: a secret gift for the other","Choosing a small treat with care shows you pay attention to the person you love.",["Agree a small amount and that the gift should be simple and tasteful. Anyone can say 'pass'.","Go into the shop together, then split up for 15 minutes to choose something.","Meet again and hand over the gifts wrapped in any paper you can find.","Open them together, looking into each other's eyes, and say why you chose it.","Finish with a coffee and a thank-you."],"Keep the gifts as a keepsake of the day.",null,null],
    "V2-207": ["Market for two: cook together whatever you choose","Choosing ingredients together and cooking afterwards is a sensory, playful way of getting closer.",["Agree that the rule of the day is to pick only what you both are happy with. Anyone can say 'pass'.","Visit a market and choose 4 ingredients, each one familiar to one of you and new to the other.","Go home and cook together, without a recipe, with music on.","Taste from each other's spoon, and swap jobs at every stage.","Dine at a nicely laid table, with a candle."],"Note down the 'dish of the day' and give it a name.",null,null],
    "V2-208": ["A themed dinner for two, dressed up","Choosing a theme and dressing for it turns an ordinary dinner into an evening you'll remember.",["Agree on the theme, and that either of you can ask to cut the evening short at any time. Anyone can say 'pass'.","Pick a simple theme, like 'Paris in the twenties' or 'gala night'.","Dress accordingly and arrive separately, as on a real date.","Dine unhurried and chat in character for a while. In public, only what is fine in public.","Finish with a toast and head home arm in arm."],"Confirm the booking and the menu beforehand.",null,"The organiser chooses the theme and the place; the other only finds out on arrival."],
    "V2-209": ["A long, slow dinner: the menu of questions","A dinner that lasts all evening lets the conversation reach places that haste never does.",["Agree that dinner is phone-free and any question can be swapped for a 'pass'.","Choose a quiet place and order something to share.","With each course, a question: about the past, the present and the future.","Answer slowly and let the other finish without interrupting.","At dessert, each says the loveliest thing they take away from the conversation."],"Confirm the booking before you leave.",null,null],
    "V2-210": ["A day out for two with a corner of our own","A day out and a corner that belongs to the two of you become, over time, a symbol of the couple.",["Agree that the day has no obligations and either of you can suggest a pause. Anyone can say 'pass'.","Choose an outing with several places and keep one stop free.","Through the day, look for a corner that is just yours: a bench, a patch of shade, a view.","There, make a small ritual: a hug, a song or a sentence. In public, only what is fine in public.","Give the corner a name and come back to it again."],"Take a photo of the corner to remember it by.",null,null],
    "V2-211": ["A day to see the city again as a couple in love","Seeing the city through the eyes of someone newly in love makes the ordinary feel new.",["Agree that the day is for looking, and you can stop at any time. Anyone can say 'pass'.","Choose 3 places you've seen a thousand times and look at them like tourists.","At each one, each points out something they'd never noticed and found beautiful.","Make a gesture of affection that is fine in public at every stop.","At the end, choose the favourite place of the day and keep it as 'ours'."],"Bring a camera, or your phone, just to photograph details.",null,null],
  },
};
